"""Shortest Common Supersequence — LCS table, then walk it backwards.

Characters in the LCS are written once; everything else is inserted from
whichever string it came from.

Time: O(n*m)   Space: O(n*m)
"""


class Solution:
    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                if str1[i - 1] == str2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        out = []
        i, j = n, m
        while i and j:
            if str1[i - 1] == str2[j - 1]:
                out.append(str1[i - 1])
                i -= 1
                j -= 1
            elif dp[i - 1][j] >= dp[i][j - 1]:
                out.append(str1[i - 1])
                i -= 1
            else:
                out.append(str2[j - 1])
                j -= 1
        out.append(str1[:i])
        out.append(str2[:j])
        return "".join(reversed(out))
